    s+=f'''</div></section><section class="invitation final-invitation"><div class="final-photo">{image('transfer',T('White Swan illuminated above its pool and garden at night','White Swan iluminada junto a su piscina y jardín de noche'))}</div><div><span class="eyebrow">{T('THE BEST PART? MAKING IT YOURS.','LO MEJOR: HACERLA TUYA.')}</span><h2>{T('See you<br><em>by the Pacific.</em>','Nos vemos<br><em>junto al Pacífico.</em>')}</h2><div class="actions"><a class="button light" href="{AIRBNB}" target="_blank" rel="noopener" data-placement="footer">{T('Find your dates','Elige tus fechas')} ↗</a><button class="hero-link" data-enquire="stay" data-placement="footer">{T('Let’s plan your stay','Planeemos tu estadía')} →</button></div></div></section></main>{footer(lang)}{components(lang)}</body></html>'''
