def day_story(lang):
    T=lambda en,es:es if lang=='es' else en
    moments=[('morning',11,T('First light','La primera luz'),T('Wake up somewhere<br><em>worth waking up for.</em>','Despierta donde<br><em>quieres estar.</em>'),T('Coffee on the balcony. A quiet ocean. Let the day begin when you’re ready.','Café en el balcón. El mar en calma. Que el día empiece cuando tú quieras.')),('afternoon',27,T('Long afternoons','Tardes sin prisa'),T('Stay for lunch.<br><em>Stay a little longer.</em>','Quédate a almorzar.<br><em>Quédate un rato más.</em>'),T('A shaded terrace, a table for your people and the pool just a few steps away.','Una terraza a la sombra, una mesa para los tuyos y la piscina a unos pasos.')),('evening',31,T('After sunset','Después del atardecer'),T('Nowhere else<br><em>you need to be.</em>','Ningún otro lugar<br><em>donde estar.</em>'),T('The house lights up. The pool turns blue. Another evening, entirely your own.','La casa se ilumina. La piscina se vuelve azul. Otra noche, solo para ustedes.'))]
    s=f'<section class="day-story section"><div class="day-heading"><span class="eyebrow">{T("A DAY AT WHITE SWAN","UN DÍA EN WHITE SWAN")}</span><p>{T("No itinerary required.","Sin itinerario.")}</p></div><div class="day-tabs" role="tablist" aria-label="{T("Imagine your day","Imagina tu día")}">'
    for i,(key,_,label,*rest) in enumerate(moments):
        active=key=='afternoon'
        s+=f'<button role="tab" id="day-tab-{key}" aria-controls="day-panel-{key}" aria-selected="{str(active).lower()}" tabindex="{0 if active else -1}" data-day-tab="{key}"><span>0{i+1}</span>{label}</button>'
    s+='</div>'
    for key,index,label,title,copy in moments:
        s+=f'<div class="day-panel" id="day-panel-{key}" role="tabpanel" aria-labelledby="day-tab-{key}" tabindex="0" {"hidden" if key!="afternoon" else ""}><figure>{photo(index,lang,sizes="(max-width: 700px) 100vw, 65vw")}<figcaption>{label} / WHITE SWAN</figcaption></figure><div><span class="day-sun" aria-hidden="true">✳</span><h2>{title}</h2><p>{copy}</p></div></div>'
    return s+'</section>'

def gallery(lang,head,components):
    T=lambda en,es:es if lang=='es' else en
    path='/es/fotos/' if lang=='es' else '/photos/';other='/photos/' if lang=='es' else '/es/fotos/'
    s=head(lang,path,T('A look around | White Swan Villa photo tour','Cada rincón | Recorrido fotográfico de White Swan'),T('Explore 36 photographs of White Swan Villa: bedrooms, open living, private infinity pool and the coast of Xanadu.','Explora 36 fotografías de White Swan: habitaciones, sala abierta, piscina infinita privada y la costa de Xanadu.'),other,'gallery')
    s+=f'<body class="editorial gallery-page" id="top">{navigation(lang,"photos")}<main id="main" class="section photo-tour"><span class="eyebrow">WHITE SWAN / {T("A CLOSER LOOK","DE CERCA")}</span><h1>{T("Picture yourself <em>here.</em>","Imagínate <em>aquí.</em>")}</h1><p class="muted">{T("The spaces, the little details, and that Pacific light.","Los espacios, los pequeños detalles y esa luz del Pacífico.")}</p><div class="gallery-filters" role="group" aria-label="{T("Filter photos","Filtrar fotos")}">'
    for key,en,es in [('all','All spaces','Todos los espacios'),('outdoors','Outdoors & pool','Exterior y piscina'),('bedrooms','Bedrooms','Habitaciones'),('living','Living & kitchen','Sala y cocina'),('details','The details','Los detalles')]:
        s+=f'<button data-photo-filter="{key}" aria-pressed="{str(key=="all").lower()}">{T(en,es)}</button>'
    s+=f'</div><p class="photo-results" role="status" aria-live="polite">36 {T("photos","fotos")}</p><div class="photo-tour-grid">'
    order=[28,29,32,9,30,27,31,35,8,10,11,12,13,14,15,16,17,18,1,7,2,0,3,4,5,6,24,25,26,19,20,21,22,23,33,34]
    for i in order:
        p=PHOTOS[i]
        s+=f'<figure data-photo-category="{p["category"]}"><a href="/assets/listing/{p["id"]}-1920.webp" data-photo-open data-caption="{escape(p["alt"][lang])}">{photo(i,lang,sizes="(max-width: 700px) 100vw, 33vw")}<span class="photo-open" aria-hidden="true">↗</span></a><figcaption>{escape(p["alt"][lang])}</figcaption></figure>'
    s+=f'''</div><noscript><p>{T('Select any photograph to open the full-size image.','Selecciona una fotografía para verla en tamaño completo.')}</p></noscript></main>{footer(lang)}<dialog class="photo-viewer" aria-label="{T('Photo viewer','Visor de fotografías')}"><div class="viewer-top"><span>WHITE SWAN</span><button data-viewer-close aria-label="{T('Close photo','Cerrar fotografía')}">×</button></div><div class="viewer-stage"><button data-photo-prev aria-label="{T('Previous photo','Foto anterior')}">←</button><img alt="" width="1600" height="1200"><button data-photo-next aria-label="{T('Next photo','Siguiente foto')}">→</button></div><div class="viewer-caption" aria-live="polite"><p></p><span></span></div></dialog>{components(lang)}</body></html>'''
    return s
